pub const WellDefinedProtocol = enum {
    git,
    git_plus_file,
    git_plus_ftp,
    git_plus_http,
    git_plus_https,
    git_plus_rsync,
    git_plus_ssh,
    http,
    https,
    ssh,
    github,
    bitbucket,
    gitlab,
    gist,
    sourcehut,
    pub fn get(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
