pub fn fromStringWithColon(protocol_with_colon: []const u8) ?WellDefinedProtocol {
            if ((protocol_with_colon.len == 0)) {
                return null;
            }
            return strings.get(bun.strings.trimSuffixComptime(protocol_with_colon, ":"));
    }

pub fn toStringWithColon(proto: WellDefinedProtocol, buf: *StringWithColonBuffer) []const u8 {
            const protocol_str = (strings.getKey(proto)).?;
            _ = @memcpy(buf[0..protocol_str.len], protocol_str);
            buf[cp_cast_int(usize, protocol_str.len)] = 58;
            return buf[0..(protocol_str.len + 1)];
    }

pub fn protocolResourceIdentifierConcatenationToken(self: WellDefinedProtocol) []const u8 {
            return (switch (self) {
.git, .git_plus_file, .git_plus_ftp, .git_plus_http, .git_plus_https, .git_plus_rsync, .git_plus_ssh, .http, .https, .ssh => "//",
.github, .bitbucket, .gitlab, .gist, .sourcehut => "",
});
    }

pub fn defaultRepresentation(self: WellDefinedProtocol) Representation {
            return (switch (self) {
.git_plus_ssh, .ssh, .git_plus_http => .sshurl,
.git_plus_https => .https,
.git_plus_file, .git_plus_ftp, .git_plus_rsync, .git => .git,
.http => .http,
.https => .https,
.github, .bitbucket, .gitlab, .gist, .sourcehut => .shortcut,
});
    }

pub fn hostProvider(self: WellDefinedProtocol) ?HostProvider {
            return (switch (self) {
.github => .github,
.bitbucket => .bitbucket,
.gitlab => .gitlab,
.gist => .gist,
.sourcehut => .sourcehut,
else => null,
});
    }

pub fn isShortcut(self: WellDefinedProtocol) bool {
            return (switch (self) {
.github, .bitbucket, .gitlab, .gist, .sourcehut => true,
else => false,
});
    }
    
    pub const strings = bun.ComptimeStringMap(WellDefinedProtocol, .{ .{ "bitbucket", .bitbucket }, .{ "gist", .gist }, .{ "git+file", .git_plus_file }, .{ "git+ftp", .git_plus_ftp }, .{ "git+http", .git_plus_http }, .{ "git+https", .git_plus_https }, .{ "git+rsync", .git_plus_rsync }, .{ "git+ssh", .git_plus_ssh }, .{ "git", .git }, .{ "github", .github }, .{ "gitlab", .gitlab }, .{ "http", .http }, .{ "https", .https }, .{ "sourcehut", .sourcehut }, .{ "ssh", .ssh } });
    
    pub const max_protocol_length: comptime_int = 9;
    
    pub const StringWithColonBuffer = [max_protocol_length + 1]u8;
};

