pub fn fromShortcut(shortcut_str: []const u8, comptime with_colon: WithColon) ?HostProvider {
            inline for (std.meta.fields(HostProvider)) |field| {
                const provider: HostProvider = @enumFromInt((if (@typeInfo(@TypeOf(field)) == .@"enum") @intFromEnum(field) else field.value));
                const shortcut_matches = std.mem.eql(u8, (switch (with_colon) {
.with_colon => provider.shortcut(),
.without_colon => provider.shortcutWithoutColon(),
}), shortcut_str);
                if (shortcut_matches) {
                    return provider;
                }
            }
            return null;
    }

pub fn fromDomain(domain_str: []const u8) ?HostProvider {
            inline for (std.meta.fields(HostProvider)) |field| {
                const provider: HostProvider = @enumFromInt((if (@typeInfo(@TypeOf(field)) == .@"enum") @intFromEnum(field) else field.value));
                if (std.mem.eql(u8, provider.domain(), domain_str)) {
                    return provider;
                }
            }
            return null;
    }

