pub fn requiresUser(user: ?[]const u8) void {
        if ((user == null)) {
            _ = @panic("Attempted to format a default SSH URL without a user. This is an irrecoverable programming bug in Bun. Please report this issue on GitHub.");
        }
}

pub fn formatSshDefault(provider: HostProvider, alloc: Allocator, user: ?[]const u8, project: []const u8, committish: ?[]const u8) ![]const u8 {
