        if (committish) |c| {
            _ = &c;
            cmsh = c;
        }
        const cmsh_sep = (if ((cmsh.len > 0)) "#" else "");
        return std.fmt.allocPrint(alloc, "git@{s}:{s}/{s}.git{s}{s}", .{ provider.domain(), user.?, project, cmsh_sep, cmsh });
}

